    "        goto done;\n"
    "    }\n"
    "    instance = created.result.value;\n"
    "    ViewportListResult views = rohr_project_viewports_get(instance);\n"
    "    if(rohr_error_check(views)) {\n"
    "        fprintf(stderr, \"%s\\n\", rohr_error_message_get(views));\n"
    "        goto done;\n"
    "    }\n"
    "    // Poll input, update each system, then present the viewport batch once.\n"
    "    for(;;) {\n"
    "        rohr_input_frame_begin();\n"
    "        SDL_Event event;\n"
    "        while((event = rohr_engine_event_poll()).type != 0) {\n"
    "            if(event.type == SDL_EVENT_QUIT) { status = 0; goto done; }\n"
    "        }\n"
    "        if(rohr_input_key_pressed_check(SDL_SCANCODE_ESCAPE)) { status = 0; goto done; }\n"
    "        Report report = rohr_engine_update();\n"
    "        if(!rohr_report_check(report)) {\n"
    "            (void)rohr_report_console_write(&report);\n"
    "            goto done;\n"
    "        }\n"
    "        Tick ticks_advanced = rohr_engine_tick_delta_get();\n"
    "        report = rohr_physics_update(ticks_advanced);\n"
    "        // Physics intentionally skips valid zero-tick frames, including pause.\n"
    "        bool physics_skipped = report.header.id == ROHR_PHYSICS_REPORT_ID &&\n"
    "            report.header.status == ROHR_REPORT_NOT_RUN && ticks_advanced == 0 &&\n"
    "            rohr_report_valid_check(&report);\n"
    "        if(!rohr_report_check(report) && !physics_skipped) {\n"
    "            (void)rohr_report_console_write(&report);\n"
    "            goto done;\n"
    "        }\n"
    "        report = rohr_graphics_sprite_frames_update(rohr_engine_tick_get(), rohr_engine_time_get());\n"
    "        if(!rohr_report_check(report)) {\n"
    "            (void)rohr_report_console_write(&report);\n"
    "            goto done;\n"
    "        }\n"
    "        if(rohr_audio_started_check()) {\n"
    "            report = rohr_audio_update();\n"
    "            if(!rohr_report_check(report)) {\n"
    "                (void)rohr_report_console_write(&report);\n"
    "                goto done;\n"
    "            }\n"
    "        }\n"
    "        report = rohr_graphics_viewports_show(views.result.value.values, views.result.value.count);\n"
    "        if(!rohr_report_check(report)) {\n"
    "            (void)rohr_report_console_write(&report);\n"
    "            goto done;\n"
    "        }\n"
    "    }\n"
    "done:\n"
    "    // Destroy owned instances before stopping their shared services.\n"
    "    result = rohr_project_destroy(instance);\n"
    "    if(rohr_error_check(result)) {\n"
    "        fprintf(stderr, \"%s\\n\", rohr_error_message_get(result));\n"
    "        status = 1;\n"
    "    }\n"
    "    if(rohr_audio_started_check()) {\n"
    "        Report report = rohr_audio_stop();\n"
    "        if(!rohr_report_check(report)) {\n"
    "            (void)rohr_report_console_write(&report);\n"
    "            status = 1;\n"
    "        }\n"
    "    }\n"
    "    rohr_graphics_stop();\n"
    "    rohr_engine_stop();\n"
    "    return status;\n"
    "}\n"
    ;

#endif
